import { expect, test } from "bun:test";
import { render } from "./src/engine";

test("interpolation escapes HTML and preserves whitespace", () => {
  expect(render(" hello {{name}}! ", { name: "<&>\"'" })).toBe(" hello &lt;&amp;&gt;&quot;&#39;! ");
  expect(render("{{{name}}}", { name: "<b>" })).toBe("<b>");
});
test("conditionals nest and use defined truthiness", () => {
  expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: true, b: false })).toBe("AC");
  expect(render("{{#if a}}yes{{else}}no{{/if}}", { a: [] })).toBe("no");
});
test("each supports this, indexes, root fallback, nesting, and else", () => {
  expect(render("{{#each items}}{{@index}}:{{this}}/{{title}};{{/each}}", { title: "T", items: ["a", "b"] })).toBe("0:a/T;1:b/T;");
  expect(render("{{#each rows}}{{#each cols}}{{this}}{{/each}}{{/each}}", { rows: [[1, 2], [3]] })).toBe("123");
  expect(render("{{#each items}}x{{else}}empty{{/each}}", { items: [] })).toBe("empty");
});
test("missing values are empty and non-scalars fail", () => {
  expect(render("x{{missing}}y", {})).toBe("xy");
  expect(() => render("{{value}}", { value: {} })).toThrow("Cannot render object");
});
test("reports structural errors with locations", () => {
  expect(() => render("{{else}}", {})).toThrow("line 1, column 1");
  expect(() => render("{{#if a}}{{/each}}", {})).toThrow("Mismatched");
  expect(() => render("{{#if a}}", {})).toThrow("Unclosed block");
  expect(() => render("{{#wat a}}{{/wat}}", {})).toThrow("Unknown");
});
# Mini Template

A dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";

render("Hello, {{name}}!", { name: "Ada" });
```

Interpolation is HTML-escaped; use triple braces (`{{{name}}}`) for raw text.
The language also supports comments, `{{#if path}}…{{else}}…{{/if}}`, and
`{{#each path}}…{{else}}…{{/each}}`. Within an `each`, `{{this}}` and
`{{@index}}` refer to the current element, while ordinary paths read from root data.

Run the CLI with:

```sh
bun run src/cli.ts TEMPLATE_FILE DATA.json
```

Run self-tests with `bun test`.
